    guide = None
    for r in range(h):
        if grid[r][0] != bg and all(v == grid[r][0] for v in grid[r]):
            guide = ('row', r, grid[r][0])
            break
    if guide is None:
        for c in range(w):
            if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
                guide = ('col', c, grid[0][c])
                break
