    if not shape:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if axis == 'row':
        # Continue the guide on the far side of the colored object.
        rows = [r for r, _ in shape]
        target = max(rows) + 1 if sum(r > pos for r in rows) >= sum(r < pos for r in rows) else min(rows) - 1
        if 0 <= target < h:
